+    // O(n) scan to detect already-sorted or reverse-sorted runs
+    bool sorted = true, reverse = true;
+    for (size_t i = 1; i < n; ++i) {
+        if (a[i] < a[i-1]) sorted = false;
+        if (a[i] > a[i-1]) reverse = false;
+        if (!sorted && !reverse) break;
+    }
+    if (sorted) return;
+    if (reverse) { std::reverse(a, a + n); return; }
