+        uint32_t v = a[i];
+        hist[0][v & 0xFF]++;
+        hist[1][(v >> 8) & 0xFF]++;
+        hist[2][(v >> 16) & 0xFF]++;
+        hist[3][(v >> 24) & 0xFF]++;
